const STG=["New lead","Contacted","Application","Approved","Test drive","Negotiation","Sold","Delivered","Follow-up","Declined","Lost"],SRC=["Website form","Sell form","Phone call","Walk-in","Referral","Facebook","Google","Other"],DOCL=["Photo ID","Proof of income","Proof of address","Proof of insurance","Title or trade-in papers","Signed contract"],TK=["Call","Text","Email","Visit","Paperwork","Other"],CLOSED=["Sold","Delivered"],DEAD=["Declined","Lost"];
